<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import {api,media,write,notify} from '../api';import {type Entry,type CookLog,today} from '../types';import Icon from '../components/Icon.vue';import Modal from '../components/Modal.vue';
const route=useRoute(),router=useRouter();const entry=ref<Entry|null>(null),error=ref(''),loading=ref(true),busy=ref(false),preview=ref(''),confirmDelete=ref(false),logOpen=ref(false),logError=ref(''),removeLog=ref<CookLog|null>(null);const log=ref<CookLog>({id:'',date:today(),note:'',rating:0});const operationError=ref('');const checked=ref<number[]>([]),cooking=ref(false),step=ref(0);const logs=computed(()=>[...(entry.value?.logs||[])].sort((a,b)=>b.date.localeCompare(a.date)));
async function load(){loading.value=true;error.value='';try{entry.value=await api<Entry>('records/'+route.params.id);if(entry.value.kind==='pantry')router.replace('/edit/'+entry.value.id)}catch(e){error.value=(e as Error).message}finally{loading.value=false}}onMounted(load);
async function mutate(action:string,extra:object={}){if(!entry.value||busy.value)return false;busy.value=true;operationError.value='';try{entry.value=await write(entry.value.id,{revision:entry.value.revision,action,...extra});return true}catch(e){operationError.value=(e as Error).message;notify(operationError.value);return false}finally{busy.value=false}}
function openLog(l?:CookLog){log.value=l?{...l}:{id:'',date:today(),note:'',rating:0};logError.value='';operationError.value='';logOpen.value=true}
async function saveLog(){if(await mutate('log',{log:log.value})){logOpen.value=false;notify('下厨的这一刻，记下了')}}
async function trash(){if(await mutate('delete')){notify('已移入回收站，30 天内可恢复');router.push('/')}}
</script>
<template><div class="page detail-page"><RouterLink to="/" class="back-link"><Icon name="arrow" :size="18"/>回到我的菜谱</RouterLink><div v-if="loading" class="empty">正在翻开这道菜…</div><div v-else-if="error" class="notice error" role="alert">{{error}}<button class="btn secondary" @click="load">重新加载</button></div><template v-else-if="entry"><div v-if="entry.deletedAt" class="empty"><Icon name="trash" :size="40"/><h2>这道菜在回收站里</h2><button class="btn primary" :disabled="busy" @click="mutate('restore')">恢复菜谱</button></div><template v-else><div class="detail-top"><div><span class="eyebrow">{{entry.category||'家的味道'}}</span><h1>{{entry.name}}</h1><div class="recipe-meta"><span v-if="entry.minutes"><Icon name="clock" :size="17"/>{{entry.minutes}} 分钟</span><span v-if="entry.servings"><Icon name="users" :size="17"/>{{entry.servings}} 人份</span><span><Icon name="flame" :size="17"/>做过 {{entry.logs.length}} 次</span></div></div><div class="detail-actions"><button class="btn secondary" :class="{liked:entry.favorite}" :disabled="busy" @click="mutate('favorite',{favorite:!entry.favorite})" :aria-label="entry.favorite?'取消收藏':'收藏菜谱'"><Icon name="heart"/><span>{{entry.favorite?'已收藏':'收藏'}}</span></button><RouterLink :to="'/edit/'+entry.id" class="btn secondary"><Icon name="edit"/>编辑菜谱</RouterLink><button class="btn primary" @click="openLog()"><Icon name="plus"/>记一次下厨</button></div></div><div class="detail-cover" v-if="entry.photoIds.length"><button @click="preview=media(entry.photoIds[0])" aria-label="查看封面大图"><img :src="media(entry.photoIds[0])" :alt="entry.name"></button><div v-if="entry.photoIds.length>1" class="detail-thumbs"><button v-for="(id,i) in entry.photoIds.slice(1)" :key="id" @click="preview=media(id)" :aria-label="'查看照片 '+(i+2)"><img :src="media(id,true)" :alt="entry.name+' 照片 '+(i+2)"></button></div></div><div class="story" v-if="entry.notes"><span>这道菜的故事与小窍门</span><p>{{entry.notes}}</p></div><div class="chip-row"><span v-for="tag in entry.tags" class="chip static"># {{tag}}</span></div><div class="detail-columns"><aside><section class="panel ingredients-panel"><div class="section-heading"><h2>准备食材</h2><span>{{entry.ingredients.length}} 种</span></div><p class="muted small" v-if="entry.ingredients.length">备好一种，点一下打个勾。</p><button v-for="(item,i) in entry.ingredients" class="ingredient-check" :class="{done:checked.includes(i)}" :aria-pressed="checked.includes(i)" @click="checked.includes(i)?checked=checked.filter(x=>x!==i):checked.push(i)"><span class="checkbox"><Icon v-if="checked.includes(i)" name="check" :size="13"/></span><span>{{item.name}}</span><strong>{{item.amount||'适量'}}</strong></button><p v-if="!entry.ingredients.length" class="muted">还没记食材，下次做的时候补上吧。</p></section></aside><div><section class="panel steps-panel"><div class="section-heading"><h2>开始做菜</h2><button v-if="entry.steps.length" class="text-btn" @click="cooking=true;step=0"><Icon name="book" :size="17"/>大字做菜模式</button></div><div v-for="(text,i) in entry.steps" class="recipe-step"><span>{{String(i+1).padStart(2,'0')}}</span><p>{{text}}</p></div><p v-if="!entry.steps.length" class="muted">还没记做法，凭记忆慢慢补齐。</p></section><section class="panel logs-panel"><div class="section-heading"><h2>下厨日记</h2><button class="text-btn" @click="openLog()"><Icon name="plus" :size="17"/>记一次</button></div><div v-if="!logs.length" class="small-empty">味道如何，下次怎么调整？<br>把每一次尝试都留在这里。</div><article class="cook-log" v-for="l in logs" :key="l.id"><div><strong>{{l.date}}</strong><span v-if="l.rating" class="rating">{{'★'.repeat(l.rating)}}{{'☆'.repeat(5-l.rating)}}</span></div><p v-if="l.note">{{l.note}}</p><div class="log-actions"><button class="text-btn" @click="openLog(l)">修改</button><button class="text-btn muted" @click="removeLog=l">删除</button></div></article></section></div></div><div class="detail-footer"><span>最近更新于 {{entry.updatedAt.slice(0,10)}}</span><button class="text-btn danger" @click="confirmDelete=true"><Icon name="trash" :size="16"/>移入回收站</button></div></template></template><Modal v-if="preview" title="美味留影" wide @close="preview=''"><img class="full-photo" :src="preview" :alt="entry?.name"></Modal><Modal v-if="logOpen" :title="log.id?'修改下厨记录':'今天，又做了这道菜'" @close="!busy&&(logOpen=false)"><form @submit.prevent="saveLog"><p v-if="operationError" class="notice error" role="alert">{{operationError}}</p><label class="field">下厨日期<span class="date-input"><input type="date" required v-model="log.date"></span></label><fieldset class="rating-field"><legend>这次味道怎么样？<span class="muted">选填</span></legend><div class="rating-buttons"><button v-for="n in 5" type="button" :aria-label="n+' 星'" :aria-pressed="log.rating===n" :class="{selected:log.rating>=n}" @click="log.rating=log.rating===n?0:n"><Icon name="star" :size="29"/></button></div></fieldset><label class="field">下厨心得<textarea v-model="log.note" rows="4" maxlength="4000" placeholder="今天少放了点盐，家里人都说刚刚好…"/></label><div class="modal-actions"><button type="button" class="btn secondary" @click="logOpen=false" :disabled="busy">取消</button><button class="btn primary" :disabled="busy">{{busy?'保存中…':'保存这次下厨'}}</button></div></form></Modal><Modal v-if="confirmDelete" title="把这道菜收起来？" @close="confirmDelete=false"><p v-if="operationError" class="notice error" role="alert">{{operationError}}</p><p>「{{entry?.name}}」会移入回收站，照片和下厨日记也会保留。30 天内可以恢复。</p><div class="modal-actions"><button class="btn secondary" @click="confirmDelete=false">保留菜谱</button><button class="btn danger-btn" @click="trash" :disabled="busy">移入回收站</button></div></Modal><Modal v-if="removeLog" title="删除这次下厨记录？" @close="removeLog=null"><p v-if="operationError" class="notice error" role="alert">{{operationError}}</p><p>仅删除 {{removeLog.date}} 的这次心得，不影响菜谱。</p><div class="modal-actions"><button class="btn secondary" @click="removeLog=null">取消</button><button class="btn danger-btn" :disabled="busy" @click="async()=>{if(await mutate('remove_log',{log:removeLog}))removeLog=null}">删除记录</button></div></Modal><Modal v-if="cooking&&entry" title="跟着步骤，慢慢做" wide @close="cooking=false"><div class="cooking-view"><span class="eyebrow">STEP {{step+1}} / {{entry.steps.length}}</span><h3>{{entry.name}}</h3><p>{{entry.steps[step]}}</p><div class="modal-actions"><button class="btn secondary" :disabled="step===0" @click="step--">上一步</button><button v-if="step<entry.steps.length-1" class="btn primary" @click="step++">下一步</button><button v-else class="btn primary" @click="cooking=false;openLog()">做好了，记一下</button></div></div></Modal></div></template>
